  (pcv = Z_to_bv 64 P_A_AOR_RET1 \/ pcv = ret_pc (Z_to_bv 64 P_A_AOR_RET1)) ->
  rw_cells bsegs m spa p24 -> Z.of_nat (cells_size p24) = 24 -> lo <= spa ->
